async function searchContestants(minScore = "", contestantName = "") {
  try {
    const body = {};
    if (minScore !== "") body.minScore = minScore;
    if (contestantName) body.name = contestantName;

    const response = await fetch(`${API_BASE_URL}/contest/search`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify(body),
    });

    if (!response.ok) throw new Error("Failed to search contestants");

    const data = await response.json();
    updateContestDisplay(data);
    showQuery(data.query, data.resultCount);

    if (contestantName && contestantName.includes("get_insider_info")) {
