-- Indexes
CREATE INDEX IF NOT EXISTS idx_contestants_votes ON contestants(votes);
CREATE INDEX IF NOT EXISTS idx_contestants_name ON contestants(name);
CREATE INDEX IF NOT EXISTS idx_contestants_odds ON contestants(odds);
CREATE INDEX IF NOT EXISTS idx_accounts_username ON accounts(username);
CREATE INDEX IF NOT EXISTS idx_sessions_username ON sessions(username);
CREATE INDEX IF NOT EXISTS idx_sessions_expires ON sessions(expires_at);
CREATE INDEX IF NOT EXISTS idx_tavern_stats_updated ON tavern_stats(updated_at);

-- Setup summary
SELECT 'Contestants: ' || COUNT(*) || ' entries' as contestants_count FROM contestants;
SELECT 'Accounts: ' || COUNT(*) || ' accounts' as accounts_count FROM accounts;
