import Fastify from "fastify";
import fastifyStatic from "@fastify/static";
import { fileURLToPath } from "url";
import { dirname, join } from "path";
import { registerRoutes } from "./routes.js";
import { ContestDatabase } from "./database.js";
import { AuthService } from "./auth.js";

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

const fastify = Fastify({
  logger: true,
});

// Register static file serving for the public directory
await fastify.register(fastifyStatic, {
  root: join(__dirname, "..", "public"),
  prefix: "/",
});

// Register API routes
registerRoutes(fastify);

// Simple database initialization with setInterval
function initializeDatabase() {
  console.log("🗄️ Waiting for database...");

  const checkDatabase = setInterval(async () => {
    try {
      const isConnected = await ContestDatabase.testConnection();
      if (isConnected) {
        clearInterval(checkDatabase);

        // Populate admin session
        await AuthService.populateAdminSession();

        console.log("✅ Database ready!");
        startServer();
      }
    } catch (error) {
      // Keep trying...
    }
  }, 1000);
}

// Start server
async function startServer() {
  try {
    const port = 3000;
    const host = "0.0.0.0";
    await fastify.listen({ host, port });

    console.log("");
    console.log("🏴‍☠️ ================================");
    console.log("🏴‍☠️  MAELSTROM'S MUG CTF STARTED");
    console.log("🏴‍☠️ ================================");
    console.log("");
    console.log(`🌐 Server: http://${host}:${port}`);
    console.log("🗄️  Database: Connected & Ready");
  } catch (err) {
    fastify.log.error(err);
    process.exit(1);
  }
}

// Start initialization
initializeDatabase();

